insert into public.quiz_questions (id, module, kind, lesson, prompt, code, options, hint, answer, explanations, active) values ('m5.q1', 'm5', 'single', 'm5.1', 'Which line runs a function when the chat form is submitted?', null, '["form.addEventListener(''submit'', handleSend);","form.submit = handleSend;","handleSend(form);","document.querySelector(handleSend);"]'::jsonb, 'Listen for an event.', '0'::jsonb, '["Correct: addEventListener waits for the event and then calls your function.","form.submit is a built-in method that sends the form; overwriting it doesn''t listen for anything.","That calls the function once, right away, not when the visitor sends a message.","querySelector finds elements by selector; it doesn''t take a function."]'::jsonb, true) on conflict (id) do update set module = excluded.module, kind = excluded.kind, lesson = excluded.lesson, prompt = excluded.prompt, code = excluded.code, options = excluded.options, hint = excluded.hint, answer = excluded.answer, explanations = excluded.explanations, active = true;
insert into public.quiz_questions (id, module, kind, lesson, prompt, code, options, hint, answer, explanations, active) values ('m5.q2', 'm5', 'single', 'm5.1', 'How do you read what the visitor typed into <input id="chat-input">?', null, '["document.querySelector(''#chat-input'').value","document.querySelector(''#chat-input'').text","document.querySelector(''#chat-input'').innerHTML","document.querySelector(''chat-input'').value"]'::jsonb, 'Inputs store what''s typed in one property.', '0'::jsonb, '["Correct: an input''s current text is in its value property.","Inputs have no text property; use value.","An <input> has no inner HTML; what''s typed lives in value.","Without the # it looks for a <chat-input> tag, not the id."]'::jsonb, true) on conflict (id) do update set module = excluded.module, kind = excluded.kind, lesson = excluded.lesson, prompt = excluded.prompt, code = excluded.code, options = excluded.options, hint = excluded.hint, answer = excluded.answer, explanations = excluded.explanations, active = true;
insert into public.quiz_questions (id, module, kind, lesson, prompt, code, options, hint, answer, explanations, active) values ('m5.q3', 'm5', 'single', 'm5.1', 'Why should you show the visitor''s message with textContent instead of innerHTML?', null, '["innerHTML would run any HTML the visitor types, which could inject code into your page","textContent is the only way to change text","innerHTML doesn''t work on <p> elements","textContent makes the text bold"]'::jsonb, 'What if someone types an <img onerror=…> tag?', '0'::jsonb, '["Correct: that''s cross-site scripting. textContent always shows text as plain text.","innerHTML can change text too; it''s just unsafe for visitor input.","innerHTML works on almost any element.","textContent doesn''t style anything."]'::jsonb, true) on conflict (id) do update set module = excluded.module, kind = excluded.kind, lesson = excluded.lesson, prompt = excluded.prompt, code = excluded.code, options = excluded.options, hint = excluded.hint, answer = excluded.answer, explanations = excluded.explanations, active = true;
insert into public.quiz_questions (id, module, kind, lesson, prompt, code, options, hint, answer, explanations, active) values ('m5.q4', 'm5', 'single', 'm5.2', 'Which visitor message does /hello|hi/i.test(message) return true for?', null, '["\"HELLO there\"","\"good morning\"","\"hey\"","\"bye\""]'::jsonb, 'The i flag.', '0'::jsonb, '["Correct: the i flag ignores capitals, so HELLO matches hello.","None of the pattern''s words appear in it.","\"hey\" is neither \"hello\" nor contains \"hi\".","\"bye\" contains neither."]'::jsonb, true) on conflict (id) do update set module = excluded.module, kind = excluded.kind, lesson = excluded.lesson, prompt = excluded.prompt, code = excluded.code, options = excluded.options, hint = excluded.hint, answer = excluded.answer, explanations = excluded.explanations, active = true;
insert into public.quiz_questions (id, module, kind, lesson, prompt, code, options, hint, answer, explanations, active) values ('m5.q5', 'm5', 'single', 'm5.2', 'What does \b do in /\bhi\b/?', null, '["Marks a word boundary, so \"hi\" must be a whole word","Makes the match bold","Matches a backslash","Matches a blank space only"]'::jsonb, 'Think about "this" vs "hi".', '0'::jsonb, '["Correct: \"hi\" now matches in \"hi there\" but not inside \"this\".","Regex finds text; it doesn''t style it.","A literal backslash is written \\\\.","A boundary is between a word character and a non-word character (or the start/end), not a space itself."]'::jsonb, true) on conflict (id) do update set module = excluded.module, kind = excluded.kind, lesson = excluded.lesson, prompt = excluded.prompt, code = excluded.code, options = excluded.options, hint = excluded.hint, answer = excluded.answer, explanations = excluded.explanations, active = true;
insert into public.quiz_questions (id, module, kind, lesson, prompt, code, options, hint, answer, explanations, active) values ('m5.q6', 'm5', 'single', 'm5.2', 'Which pattern matches an email address like ana.rao@uni.edu?', null, '["/\\w+@\\w+\\.\\w+/","/@/","/email/i","/\\d+@\\d+/"]'::jsonb, 'Build it from parts.', '0'::jsonb, '["Correct: letters, @, letters, a real dot, letters.","A lone @ also matches \"@ana\", which isn''t an email.","That matches the word \"email\", not an address.","\\d is digits only, so letters wouldn''t match."]'::jsonb, true) on conflict (id) do update set module = excluded.module, kind = excluded.kind, lesson = excluded.lesson, prompt = excluded.prompt, code = excluded.code, options = excluded.options, hint = excluded.hint, answer = excluded.answer, explanations = excluded.explanations, active = true;
insert into public.quiz_questions (id, module, kind, lesson, prompt, code, options, hint, answer, explanations, active) values ('m5.q7', 'm5', 'single', 'm5.3', 'Your bot checks intents in order: greeting /\b(hi|hello)\b/i first, then skills /skill/i. What does it reply to "Hi, what are your skills?"', null, '["The greeting reply, because greeting is checked first","The skills reply","Both replies","The fallback reply"]'::jsonb, 'First match wins.', '0'::jsonb, '["Correct: the first matching intent wins. Put specific intents (skills) before general ones (greeting).","Skills matches too, but it''s checked after greeting has already won.","The loop returns at the first match, so there''s only one reply.","Two intents match, so the fallback isn''t used."]'::jsonb, true) on conflict (id) do update set module = excluded.module, kind = excluded.kind, lesson = excluded.lesson, prompt = excluded.prompt, code = excluded.code, options = excluded.options, hint = excluded.hint, answer = excluded.answer, explanations = excluded.explanations, active = true;
insert into public.quiz_questions (id, module, kind, lesson, prompt, code, options, hint, answer, explanations, active) values ('m5.q8', 'm5', 'single', 'm5.3', 'What''s a good fallback reply when no intent matches?', null, '["\"Sorry, I didn''t get that. Try asking about projects, skills or contact.\"","\"Error.\"","Nothing: leave the chat silent","Repeat the visitor''s message back to them"]'::jsonb, 'Help the visitor get unstuck.', '0'::jsonb, '["Correct: it admits the miss and tells visitors what they can ask.","Unhelpful: the visitor doesn''t know what to try next.","Silence makes the chat look broken.","Echoing isn''t an answer and doesn''t help them."]'::jsonb, true) on conflict (id) do update set module = excluded.module, kind = excluded.kind, lesson = excluded.lesson, prompt = excluded.prompt, code = excluded.code, options = excluded.options, hint = excluded.hint, answer = excluded.answer, explanations = excluded.explanations, active = true;
insert into public.quiz_questions (id, module, kind, lesson, prompt, code, options, hint, answer, explanations, active) values ('m5.q9', 'm5', 'order', 'm5.3', 'Put the steps in order for handling one message.', null, '["Show the reply in the chat log","Read input.value","Find the first intent whose pattern matches","Prevent the form from reloading the page"]'::jsonb, 'Start with what the browser does by default.', '[3,1,2,0]'::jsonb, '["Stop the reload, read what was typed, find the matching intent (or the fallback), then show the reply."]'::jsonb, true) on conflict (id) do update set module = excluded.module, kind = excluded.kind, lesson = excluded.lesson, prompt = excluded.prompt, code = excluded.code, options = excluded.options, hint = excluded.hint, answer = excluded.answer, explanations = excluded.explanations, active = true;
insert into public.quiz_questions (id, module, kind, lesson, prompt, code, options, hint, answer, explanations, active) values ('m5.q10', 'm5', 'single', 'm5.4', 'Which CSS keeps the chat window in the bottom-right corner while the page scrolls?', null, '["#chat { position: fixed; bottom: 16px; right: 16px; }","#chat { float: right; }","#chat { position: relative; bottom: 0; }","#chat { text-align: right; }"]'::jsonb, 'Pinned to the window.', '0'::jsonb, '["Correct: fixed pins it to the window; bottom and right set the corner.","Float moves it to the right of its line, and it still scrolls away.","Relative only nudges it from its normal place in the page.","That aligns the text inside it, not the box itself."]'::jsonb, true) on conflict (id) do update set module = excluded.module, kind = excluded.kind, lesson = excluded.lesson, prompt = excluded.prompt, code = excluded.code, options = excluded.options, hint = excluded.hint, answer = excluded.answer, explanations = excluded.explanations, active = true;
insert into public.quiz_questions (id, module, kind, lesson, prompt, code, options, hint, answer, explanations, active) values ('m5.q11', 'm5', 'single', 'm5.4', 'Spot the bug. The newest messages end up hidden below the bottom of the chat.', '1  #chat-log { max-height: 220px; overflow-y: auto; }
insert into public.quiz_questions (id, module, kind, lesson, prompt, code, options, hint, answer, explanations, active) values ('m5.q12', 'm5', 'single', 'm5.5', 'const m = "My name is Sam".match(/my name is (\w+)/i); What is m[1]?', null, '["\"Sam\"","\"My name is Sam\"","\"my\"","true"]'::jsonb, 'Index 1 is the first ( ) group.', '0'::jsonb, '["Correct: m[1] is what the first capture group ( ) matched.","That''s m[0], the whole match.","\"my\" is part of the pattern outside the group.","match returns an array (or null); test returns true/false."]'::jsonb, true) on conflict (id) do update set module = excluded.module, kind = excluded.kind, lesson = excluded.lesson, prompt = excluded.prompt, code = excluded.code, options = excluded.options, hint = excluded.hint, answer = excluded.answer, explanations = excluded.explanations, active = true;
